// Services (IOrderService) come from DI, not binding
// id from route, page from query, request from body

public sealed class OrderId
{
    public Guid Value { get; }
    public OrderId(Guid value) => Value = value;
}

public sealed class OrderIdBinder : IModelBinder
{
    public Task BindModelAsync(ModelBindingContext ctx)
    {
        var raw = ctx.ValueProvider.GetValue(ctx.ModelName).FirstValue;
        if (Guid.TryParse(raw, out var guid))
        {
            ctx.Result = ModelBindingResult.Success(new OrderId(guid));
            return Task.CompletedTask;
        }
        ctx.ModelState.TryAddModelError(ctx.ModelName, "Invalid order id");
        ctx.Result = ModelBindingResult.Failed();
        return Task.CompletedTask;
    }
}

[ModelBinder(BinderType = typeof(OrderIdBinder))]
public sealed record GetOrderRequest(OrderId Id);

